(function () {

    RED.editor.registerEditPane(
        "editor-tab-description",
        function (node) {

            return {

                label: RED._("editor-tab.description"),

                name: RED._("editor-tab.description"),

                iconClass: "fa fa-file-text-o",

                create: function (container) {

                    this.editor = buildDescriptionForm(
                        container,
                        node
                    );

                },

                resize: function () {

                    this.editor.resize();

                },

                close: function () {

                    this.editor.destroy();

                    this.editor = null;

                },

                show: function () {

                    this.editor.focus();

                },

                apply: function (editState) {

                    var oldInfo = node.info;
                    var newInfo = this.editor.getValue();

                    if (oldInfo) {

                        if (newInfo.trim() === "") {

                            editState.changed = true;
                            editState.changes.info = oldInfo;

                            delete node.info;

                        } else if (newInfo !== oldInfo) {

                            editState.changed = true;
                            editState.changes.info = oldInfo;

                            node.info = newInfo;

                        }

                    } else {

                        if (newInfo.trim() !== "") {

                            editState.changed = true;
                            editState.changes.info = undefined;

                            node.info = newInfo;

                        }

                    }

                }

            };

        }
    );


    function buildDescriptionForm(container, node) {

        var dialogForm = $(
            '<form class="dialog-form form-horizontal" ' +
            'autocomplete="off" ' +
            'style="' +
            'height:100%;' +
            'display:flex;' +
            'flex-direction:column;' +
            '">'
        ).appendTo(container);


        // ====================================================
        // EDITOR
        // ====================================================

        var row = $(
            '<div class="form-row node-text-editor-row" ' +
            'style="' +
            'position:relative;' +
            'padding-top:4px;' +
            'flex:1;' +
            'min-height:0;' +
            '">'
        ).appendTo(dialogForm);


        var editorId =
            "node-info-input-info-editor-" +
            Math.floor(1000 * Math.random());


        $(
            '<div ' +
            'class="node-text-editor" ' +
            'id="' + editorId + '" ' +
            'style="height:100%;">' +
            '</div>'
        ).appendTo(row);


        var nodeInfoEditor = RED.editor.createEditor({

            id: editorId,

            mode: "ace/mode/markdown",

            stateId:
                RED.editor.generateViewStateId(
                    "node",
                    node,
                    "nodeinfo"
                ),

            value: node.info || ""

            ,

            markdownFooter: function (footerContainer, expandedEditor) {

                addAIRewriteControls(footerContainer, expandedEditor);

            }

        });


        node.infoEditor = nodeInfoEditor;


        addAIRewriteControls(dialogForm, nodeInfoEditor, function (output) {

            node.info = output;

        });


        return nodeInfoEditor;

    }


    function addAIRewriteControls(container, editor, onRewrite) {

        // ====================================================
        // AI INPUT ROW
        // ====================================================

        var bottomRow = $(
            '<div ' +
            'style="' +
            'display:flex;' +
            'gap:8px;' +
            'margin:8px 0 0 0;' +
            'flex-shrink:0;' +
            'align-items:center;' +
            '">'
        ).appendTo(container);


        var aiInput = $(
            '<input ' +
            'type="text" ' +
            'class="form-control" ' +
            'placeholder="Ask AI to rewrite..." ' +
            'style="' +
            'flex:1;' +
            'min-width:0;' +
            '">'
        ).appendTo(bottomRow);


        var aiButton = $(
            '<button ' +
            'type="button" ' +
            'class="red-ui-button" ' +
            'style="flex-shrink:0;">' +
            '<i class="fa fa-magic"></i> ' +
            'Rewrite' +
            '</button>'
        ).appendTo(bottomRow);


        // ====================================================
        // OPENAI
        // ====================================================

        async function rewriteWithAI() {

            var instruction =
                String(
                    aiInput.val() || ""
                ).trim();


            if (!instruction) {

                aiInput.focus();

                return;

            }


            var existingValue =
                editor.getValue() || "";

            var openAIApiKey =
                String(
                    RED.settings.get(
                        "aiRewriter.openaiApiKey",
                        ""
                    ) || ""
                ).trim();


            if (!openAIApiKey) {

                RED.notify(
                    "Enter your OpenAI API key in Settings > AI Rewriter.",
                    {
                        type: "error",
                        timeout: 5000
                    }
                );

                return;

            }


            aiButton
                .prop("disabled", true)
                .html(
                    '<i class="fa fa-spinner fa-spin"></i> Rewriting...'
                );


            try {

                var response =
                    await fetch(
                        "https://api.openai.com/v1/responses",
                        {
                            method: "POST",

                            headers: {
                                "Content-Type":
                                    "application/json",

                                "Authorization":
                                    "Bearer " + openAIApiKey
                            },

                            body: JSON.stringify({

                                model: "gpt-5.6-luna",

                                input: [
                                    {
                                        role: "system",

                                        content: [
                                            {
                                                type:
                                                    "input_text",

                                                text:
                                                    "You are an expert content editor. " +
                                                    "Rewrite the provided content according " +
                                                    "to the user's instruction. " +
                                                    "Return ONLY the rewritten content. " +
                                                    "Do not explain your changes."
                                            }
                                        ]
                                    },
                                    {
                                        role: "user",

                                        content: [
                                            {
                                                type:
                                                    "input_text",

                                                text:
                                                    "USER INSTRUCTION:\n\n" +
                                                    instruction +
                                                    "\n\n" +

                                                    "EXISTING CONTENT:\n\n" +
                                                    (
                                                        existingValue ||
                                                        "(empty)"
                                                    )
                                            }
                                        ]
                                    }
                                ],

                                stream: true

                            }

                            )
                        }
                    );


                if (!response.ok) {

                    var errorText =
                        await response.text();

                    throw new Error(
                        errorText ||
                        "OpenAI API request failed"
                    );

                }


                var output = "";


                if (response.body && response.body.getReader) {

                    output =
                        await readStreamingResponse(
                            response,
                            function (value) {

                                editor.setValue(
                                    value,
                                    -1
                                );

                                if (onRewrite) {

                                    onRewrite(value);

                                }

                            }
                        );

                } else {

                    output =
                        extractOutputText(
                            await response.json()
                        );

                }


                output =
                    String(
                        output || ""
                    ).trim();


                if (!output) {

                    throw new Error(
                        "OpenAI returned empty content"
                    );

                }


                editor.setValue(
                    output,
                    -1
                );


                if (onRewrite) {

                    onRewrite(output);

                }


                // Clear prompt
                aiInput.val("");


                // Focus editor
                editor.focus();


            } catch (error) {

                console.error(
                    "OpenAI Error:",
                    error
                );


                RED.notify(
                    "AI rewrite failed: " +
                    error.message,
                    {
                        type: "error",
                        timeout: 5000
                    }
                );

            } finally {

                aiButton
                    .prop("disabled", false)
                    .html(
                        '<i class="fa fa-magic"></i> Rewrite'
                    );

            }

        }


        async function readStreamingResponse(response, onUpdate) {

            var reader = response.body.getReader();
            var decoder = new TextDecoder();
            var buffer = "";
            var output = "";


            function handleEvent(rawEvent) {

                var dataLines =
                    rawEvent
                        .replace(/\r\n/g, "\n")
                        .split("\n")
                        .filter(function (line) {

                            return line.indexOf("data:") === 0;

                        })
                        .map(function (line) {

                            return line.substring(5).trim();

                        });


                dataLines.forEach(function (data) {

                    if (!data || data === "[DONE]") {

                        return;

                    }


                    var eventData;

                    try {

                        eventData = JSON.parse(data);

                    } catch (err) {

                        return;

                    }


                    var delta = eventData.delta;

                    if (
                        eventData.type ===
                        "response.output_text.delta" &&
                        delta
                    ) {

                        output += delta;
                        onUpdate(output);

                    }


                    if (
                        eventData.type ===
                        "response.output_text.done" &&
                        eventData.text
                    ) {

                        output = eventData.text;
                        onUpdate(output);

                    }


                    if (
                        eventData.type ===
                        "response.completed" &&
                        eventData.response
                    ) {

                        var completedOutput =
                            extractOutputText(eventData.response);

                        if (completedOutput) {

                            output = completedOutput;
                            onUpdate(output);

                        }

                    }

                });

            }


            while (true) {

                var read = await reader.read();

                if (read.done) {

                    break;

                }


                buffer += decoder.decode(
                    read.value,
                    {
                        stream: true
                    }
                );

                buffer = buffer.replace(/\r\n/g, "\n");


                var boundary;

                while ((boundary = buffer.indexOf("\n\n")) !== -1) {

                    handleEvent(buffer.slice(0, boundary));
                    buffer = buffer.slice(boundary + 2);

                }

            }


            buffer += decoder.decode();

            if (buffer.trim()) {

                handleEvent(buffer);

            }


            return output;

        }


        function extractOutputText(result) {

            var output =
                result.output_text;


            if (!output && result.output) {

                output = "";

                result.output.forEach(
                    function (item) {

                        if (
                            item.type ===
                            "message"
                        ) {

                            (item.content || [])
                                .forEach(
                                    function (content) {

                                        if (
                                            content.type ===
                                            "output_text"
                                        ) {

                                            output +=
                                                content.text ||
                                                "";

                                        }

                                    }
                                );

                        }

                    }
                );

            }


            return output;

        }


        // ====================================================
        // BUTTON CLICK
        // ====================================================

        aiButton.on(
            "click",
            function (event) {

                event.preventDefault();

                rewriteWithAI();

            }
        );


        // ====================================================
        // ENTER KEY
        // ====================================================

        aiInput.on(
            "keydown",
            function (event) {

                if (
                    event.key === "Enter" &&
                    !event.shiftKey
                ) {

                    event.preventDefault();

                    rewriteWithAI();

                }

            }
        );


        // ====================================================
        // REFERENCES
        // ====================================================

    }

})();
